package tv.plus.pro.unified;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import android.view.*;import android.widget.*;import java.util.*;
public class FileBrowserActivity extends Activity{
 LinearLayout list;Uri tree,current;ArrayList<Uri> history=new ArrayList<>();int color=0xff10102b;
 @Override public void onCreate(Bundle b){super.onCreate(b);build();String saved=getPreferences(0).getString("tree",null);if(saved!=null){try{tree=Uri.parse(saved);current=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));showDir();return;}catch(Exception ignored){}}choose();}
 void build(){LinearLayout base=new LinearLayout(this);base.setOrientation(1);base.setPadding(20,14,20,14);base.setBackgroundColor(color);TextView title=button("▶ TV+  Dosyalar",()->{});title.setTextSize(25);base.addView(title);LinearLayout bar=new LinearLayout(this);bar.setOrientation(0);TextView back=button("← Geri",()->back());TextView select=button("Klasör Seç",()->choose());bar.addView(back,new LinearLayout.LayoutParams(0,-2,1));bar.addView(select,new LinearLayout.LayoutParams(0,-2,1));base.addView(bar);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);base.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(base);}
 TextView button(String s,Runnable r){TextView v=new TextView(this);v.setText(s);v.setTextSize(17);v.setTextColor(-1);v.setPadding(18,16,18,16);v.setFocusable(true);v.setBackgroundColor(0xff312459);v.setOnFocusChangeListener((w,f)->v.setBackgroundColor(f?0xff8840df:0xff312459));v.setOnClickListener(w->r.run());return v;}
 void add(String s,Runnable r){TextView v=button(s,r);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);list.addView(v,p);}
 void choose(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,1);}catch(Exception e){error("Klasör seçici açılamadı: "+e.getMessage());}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=1||result!=RESULT_OK||data==null)return;tree=data.getData();if(tree==null)return;try{getContentResolver().takePersistableUriPermission(tree,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getPreferences(0).edit().putString("tree",tree.toString()).apply();current=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));history.clear();showDir();}catch(Exception e){error(e.getMessage());}}
 void showDir(){list.removeAllViews();if(tree==null||current==null){add("Klasör seç",()->choose());return;}add("📂  "+current.getLastPathSegment(),()->{});Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(current));String[] cols={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE};try(Cursor c=getContentResolver().query(children,cols,null,null,null)){if(c==null){add("Klasör okunamadı",()->{});return;}int count=0;while(c.moveToNext()){String id=c.getString(0),name=c.getString(1),mime=c.getString(2);long size=c.isNull(3)?-1:c.getLong(3);boolean folder=DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,id);String label=(folder?"📁  ":"📄  ")+name+(folder?"":size>=0?"  ("+(size/1024)+" KB)":"");add(label,()->{if(folder){history.add(current);current=uri;showDir();}else open(uri,mime,name);});count++;}if(count==0)add("Bu klasör boş",()->{});}catch(Exception e){error("Klasör okunamadı: "+e.getMessage());}}
 void open(Uri uri,String mime,String name){if(mime!=null&&mime.startsWith("video/")){Intent i=new Intent(this,VideoPlayerActivity.class);i.setDataAndType(uri,mime);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);return;}if(mime!=null&&mime.startsWith("image/")){Intent i=new Intent(this,VideoPlayerActivity.class);i.setDataAndType(uri,mime);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);return;}try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,mime==null?"*/*":mime);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){error("Bu dosya türünü açacak uygulama bulunamadı: "+name);}}
 void error(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("Tamam",null).show();}
 void back(){if(!history.isEmpty()){current=history.remove(history.size()-1);showDir();}else finish();}
 @Override public void onBackPressed(){back();}
}